"use client"

import { useEffect, useRef, useState, useSyncExternalStore } from "react"
import {
	DialStore,
	isEasingConfigValue,
	isSpringConfigValue,
	type ControlMeta,
	type DialPadAxis,
	type DialValue,
	type EasingConfig,
	type PanelConfig,
	type Preset,
	type TransitionConfig,
} from "dialkit/store"
import {
	RiAddLine,
	RiArrowDownSLine,
	RiCheckLine,
	RiDeleteBinLine,
	RiFileCopyLine,
	RiRestartLine,
} from "@remixicon/react"
import { cn } from "@/lib/utils"
import {
	Pane,
	PaneAction,
	PaneHeader,
	PaneLabel,
} from "@/components/substrate/pane"
import {
	CollapsiblePane,
	CollapsiblePaneContent,
	CollapsiblePaneHeader,
	CollapsiblePaneLabel,
} from "@/components/substrate/collapsible-pane"
import {
	Action,
	ActionControls,
	ActionLabel,
} from "@/components/substrate/action"
import { NumberSlider } from "@/components/substrate/number-slider"
import { NumberInput } from "@/components/substrate/number-input"
import { Toggle } from "@/components/substrate/toggle"
import {
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from "@/components/substrate/select"
import { ColourPicker } from "@/components/substrate/colour-picker"
import { TextArea } from "@/components/substrate/text-area"
import { EasingCurveEditor } from "@/components/substrate/easing-curve-editor"
import {
	ToggleGroup,
	ToggleGroupItem,
} from "@/components/substrate/toggle-group"
import { SpringCurve, SpringFields } from "@/components/substrate/spring-editor"
import { XYPad, type XYPadAxis } from "@/components/substrate/xy-pad"
import { ImagePicker } from "@/components/substrate/image-picker"
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/substrate/popover"
import {
	formatShortcut,
	getActiveShortcut,
	retainShortcutListener,
	subscribeActiveShortcut,
} from "@/lib/substrate/controls-shortcuts"
import {
	DEFAULT_PHYSICS_SPRING,
	DEFAULT_TIME_SPRING,
	springMode,
} from "@/lib/substrate/spring"

// Renders the panels registered with useControls. The store and config format
// come from DialKit (MIT, © Josh Puckett); the controls are Substrate's own.

const NO_PANELS: PanelConfig[] = []
const NO_PRESETS: Preset[] = []

// ── Controls ──

type ControlsProps = {
	/** Render only the panel with this name or id; all panels when omitted */
	panel?: string
}

function Controls({
	panel,
	className,
	...props
}: ControlsProps & React.ComponentProps<"div">) {
	const panels = useSyncExternalStore(
		(listener) => DialStore.subscribeGlobal(listener),
		() => DialStore.getPanels("panel"),
		() => NO_PANELS,
	)
	const visible = panel
		? panels.filter((p) => p.name === panel || p.id === panel)
		: panels

	useEffect(() => retainShortcutListener(), [])

	return (
		<div
			data-slot="controls"
			className={cn("space-y-3", className)}
			{...props}
		>
			{visible.map((p) => (
				<ControlsPanel key={p.id} panel={p} />
			))}
		</div>
	)
}

// ── ControlsPanel ──

type ControlsPanelProps = {
	panel: PanelConfig
}

function ControlsPanel({
	panel,
	...props
}: ControlsPanelProps & React.ComponentProps<"div">) {
	const values = useSyncExternalStore(
		(listener) => DialStore.subscribe(panel.id, listener),
		() => DialStore.getValues(panel.id),
		() => DialStore.getValues(panel.id),
	)

	return (
		<Pane data-slot="controls-panel" {...props}>
			<PaneHeader className="gap-1">
				<PaneLabel className="mr-auto truncate">{panel.name}</PaneLabel>
				<ControlsVersions panelId={panel.id} panelName={panel.name} />
				<ControlsCopy
					panelName={panel.name}
					getText={() => copyInstruction(panel.name, values)}
				/>
				<PaneAction
					aria-label={`Reset ${panel.name}`}
					title="Reset"
					onClick={() => DialStore.resetValues(panel.id)}
				>
					<RiRestartLine />
				</PaneAction>
			</PaneHeader>
			<div className="space-y-1">
				{panel.controls.map((control) => (
					<ControlsField
						key={control.path}
						panelId={panel.id}
						control={control}
						values={values}
					/>
				))}
			</div>
		</Pane>
	)
}

// ── ControlsField ──

type ControlsFieldProps = {
	panelId: string
	control: ControlMeta
	values: Record<string, DialValue>
}

function ControlsField({ panelId, control, values }: ControlsFieldProps) {
	const value = values[control.path]
	const update = (next: DialValue) =>
		DialStore.updateValue(panelId, control.path, next)
	const activeShortcut = useSyncExternalStore(
		subscribeActiveShortcut,
		getActiveShortcut,
		() => null,
	)
	const shortcut = control.shortcut?.key || control.shortcut?.interaction
		? control.shortcut
		: undefined
	const shortcutProps = shortcut
		? {
				shortcut: formatShortcut(control, shortcut),
				active:
					activeShortcut?.panelId === panelId &&
					activeShortcut.path === control.path,
			}
		: {}

	switch (control.type) {
		case "folder":
			return (
				<CollapsiblePane
					defaultOpen={control.defaultOpen ?? true}
					className="px-0"
				>
					<CollapsiblePaneHeader>
						<CollapsiblePaneLabel>{control.label}</CollapsiblePaneLabel>
					</CollapsiblePaneHeader>
					<CollapsiblePaneContent className="space-y-1 pl-4">
						{control.children?.map((child) => (
							<ControlsField
								key={child.path}
								panelId={panelId}
								control={child}
								values={values}
							/>
						))}
					</CollapsiblePaneContent>
				</CollapsiblePane>
			)

		case "slider": {
			const step = control.step ?? 1
			return (
				<ControlsRow label={control.label} {...shortcutProps}>
					<NumberSlider
						value={typeof value === "number" ? value : 0}
						onChange={update}
						min={control.min}
						max={control.max}
						step={step}
						precision={decimals(step)}
					/>
				</ControlsRow>
			)
		}

		case "toggle": {
			const pressed = value === true
			return (
				<ControlsRow label={control.label} {...shortcutProps}>
					<Toggle pressed={pressed} onPressedChange={update}>
						{pressed ? "On" : "Off"}
					</Toggle>
				</ControlsRow>
			)
		}

		case "select":
			return (
				<ControlsRow label={control.label}>
					<Select
						value={typeof value === "string" ? value : ""}
						onValueChange={update}
					>
						<SelectTrigger>
							<SelectValue />
						</SelectTrigger>
						<SelectContent>
							{control.options?.map((option) => {
								const item =
									typeof option === "string"
										? { value: option, label: option }
										: option
								return (
									<SelectItem key={item.value} value={item.value}>
										{item.label}
									</SelectItem>
								)
							})}
						</SelectContent>
					</Select>
				</ControlsRow>
			)

		case "color": {
			const colour = typeof value === "string" ? value : "#000000"
			return (
				<ControlsRow label={control.label}>
					<ColourPicker value={colour} onChange={update} />
					<span className="text-[11px] font-mono text-muted-foreground truncate">
						{colour}
					</span>
				</ControlsRow>
			)
		}

		case "text":
			return (
				<div data-slot="controls-text" className="space-y-1 py-1">
					<ActionLabel className="w-auto">{control.label}</ActionLabel>
					<TextArea
						value={typeof value === "string" ? value : ""}
						onChange={(event) => update(event.target.value)}
						placeholder={control.placeholder}
						minRows={1}
					/>
				</div>
			)

		case "transition":
			if (!isSpringConfigValue(value) && !isEasingConfigValue(value)) return null
			return (
				<ControlsTransition
					panelId={panelId}
					path={control.path}
					label={control.label}
					value={value}
					onChange={update}
				/>
			)

		case "image":
			return (
				<div data-slot="controls-image" className="space-y-1 py-1">
					<ActionLabel className="w-auto">{control.label}</ActionLabel>
					<ImagePicker
						value={typeof value === "string" ? value : ""}
						onChange={update}
						options={control.options}
					/>
				</div>
			)

		case "pad": {
			const x = padAxis(control.pad?.x)
			const y = padAxis(control.pad?.y)
			const point = isPadValue(value) ? value : { x: 0, y: 0 }
			return (
				<div data-slot="controls-pad" className="space-y-1 py-1">
					<ActionLabel className="w-auto">{control.label}</ActionLabel>
					<XYPad
						aria-label={control.label}
						value={point}
						onChange={update}
						x={x}
						y={y}
					/>
					<ControlsRow label={control.pad?.labels?.x ?? "X"}>
						<NumberInput
							value={point.x}
							onChange={(next) => update({ ...point, x: next })}
							min={x.min}
							max={x.max}
							step={x.step}
							precision={decimals(x.step)}
						/>
					</ControlsRow>
					<ControlsRow label={control.pad?.labels?.y ?? "Y"}>
						<NumberInput
							value={point.y}
							onChange={(next) => update({ ...point, y: next })}
							min={y.min}
							max={y.max}
							step={y.step}
							precision={decimals(y.step)}
						/>
					</ControlsRow>
				</div>
			)
		}

		case "action":
			return (
				<button
					type="button"
					data-slot="controls-action"
					className={cn(
						"h-7 w-full rounded-md bg-accent px-2 text-xs font-medium text-accent-foreground transition-colors",
						"hover:bg-accent/80 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50",
					)}
					onClick={() => DialStore.triggerAction(panelId, control.path)}
				>
					{control.label}
				</button>
			)

		default:
			return null
	}
}

// ── ControlsRow ──

type ControlsRowProps = {
	label: string
	/** Shortcut description, such as "R+Scroll" */
	shortcut?: string
	/** The shortcut is held and this row is being adjusted */
	active?: boolean
}

function ControlsRow({
	label,
	shortcut,
	active,
	className,
	children,
	...props
}: ControlsRowProps & React.ComponentProps<"div">) {
	return (
		<Action
			data-shortcut-active={active || undefined}
			className={cn(
				"-mx-1 rounded-md px-1 transition-colors",
				active && "bg-accent/60",
				className,
			)}
			{...props}
		>
			<ActionLabel
				className="flex min-w-0 items-center gap-1"
				title={shortcut ? `${label} (${shortcut})` : label}
			>
				<span className="truncate">{label}</span>
				{shortcut && (
					<kbd
						data-slot="controls-shortcut"
						className={cn(
							"shrink-0 font-mono text-[10px] text-muted-foreground/70",
							active && "text-foreground",
						)}
					>
						{shortcut.split("+")[0]}
					</kbd>
				)}
			</ActionLabel>
			<ActionControls>{children}</ActionControls>
		</Action>
	)
}

// ── ControlsVersions ──

type ControlsVersionsProps = {
	panelId: string
	panelName: string
}

// Saved versions of a panel's values, from DialKit's presets. "Version 1" is
// the values before any version was chosen.
function ControlsVersions({ panelId, panelName }: ControlsVersionsProps) {
	const [open, setOpen] = useState(false)
	const presets = useSyncExternalStore(
		(listener) => DialStore.subscribe(panelId, listener),
		() => {
			const list = DialStore.getPresets(panelId)
			return list.length > 0 ? list : NO_PRESETS
		},
		() => NO_PRESETS,
	)
	const activeId = useSyncExternalStore(
		(listener) => DialStore.subscribe(panelId, listener),
		() => DialStore.getActivePresetId(panelId),
		() => null,
	)
	const activeName = presets.find((preset) => preset.id === activeId)?.name ?? "Version 1"

	const choose = (presetId: string | null) => {
		if (presetId) DialStore.loadPreset(panelId, presetId)
		else DialStore.clearActivePreset(panelId)
		setOpen(false)
	}

	return (
		<Popover open={open} onOpenChange={setOpen}>
			<PopoverTrigger
				data-slot="controls-versions"
				aria-label={`${panelName} versions`}
				className={cn(
					"flex h-6 min-w-0 items-center gap-0.5 rounded px-1.5 text-xs text-muted-foreground transition-colors",
					"hover:bg-accent hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50",
					"data-[state=open]:bg-accent data-[state=open]:text-foreground",
				)}
			>
				<span className="truncate">{activeName}</span>
				<RiArrowDownSLine className="size-3.5 shrink-0" />
			</PopoverTrigger>
			<PopoverContent align="end" className="w-48 p-1">
				<div role="group" aria-label="Versions" className="flex flex-col">
					<ControlsVersionItem
						name="Version 1"
						selected={activeId === null}
						onSelect={() => choose(null)}
					/>
					{presets.map((preset) => (
						<ControlsVersionItem
							key={preset.id}
							name={preset.name}
							selected={preset.id === activeId}
							onSelect={() => choose(preset.id)}
							onDelete={() => DialStore.deletePreset(panelId, preset.id)}
						/>
					))}
				</div>
				<div role="separator" className="-mx-1 my-1 h-px bg-border" />
				<button
					type="button"
					className={cn(
						"flex h-7 w-full items-center gap-2 rounded-md px-2 text-xs outline-none transition-colors",
						"hover:bg-accent focus-visible:bg-accent",
						"[&_svg]:size-3.5 [&_svg]:shrink-0",
					)}
					onClick={() => {
						DialStore.saveNewPreset(panelId)
						setOpen(false)
					}}
				>
					<RiAddLine />
					New version
				</button>
			</PopoverContent>
		</Popover>
	)
}

type ControlsVersionItemProps = {
	name: string
	selected: boolean
	onSelect: () => void
	onDelete?: () => void
}

function ControlsVersionItem({
	name,
	selected,
	onSelect,
	onDelete,
}: ControlsVersionItemProps) {
	return (
		<div className="group/version flex items-center rounded-md hover:bg-accent has-focus-visible:bg-accent">
			<button
				type="button"
				aria-pressed={selected}
				className="flex h-7 min-w-0 flex-1 items-center gap-2 px-2 text-left text-xs outline-none"
				onClick={onSelect}
			>
				<RiCheckLine
					aria-hidden="true"
					className={cn("size-3.5 shrink-0", !selected && "invisible")}
				/>
				<span className="truncate">{name}</span>
			</button>
			{onDelete && (
				<button
					type="button"
					aria-label={`Delete ${name}`}
					title="Delete"
					className={cn(
						"mr-1 flex size-5 shrink-0 items-center justify-center rounded text-muted-foreground outline-none transition",
						"opacity-0 group-hover/version:opacity-100 focus-visible:opacity-100",
						"hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50",
						"[&_svg]:size-3",
					)}
					onClick={onDelete}
				>
					<RiDeleteBinLine />
				</button>
			)}
		</div>
	)
}

// ── ControlsCopy ──

type ControlsCopyProps = {
	panelName: string
	/** The text to copy, built when clicked */
	getText: () => string
}

// Copies the current values as an instruction an agent can apply to the
// code, in DialKit's format
function ControlsCopy({ panelName, getText }: ControlsCopyProps) {
	const [copied, setCopied] = useState(false)
	const timeout = useRef<ReturnType<typeof setTimeout>>(undefined)
	useEffect(() => () => clearTimeout(timeout.current), [])

	const copy = async () => {
		try {
			await navigator.clipboard.writeText(getText())
		} catch {
			// Clipboard access can be refused; the icon stays as it was
			return
		}
		setCopied(true)
		clearTimeout(timeout.current)
		timeout.current = setTimeout(() => setCopied(false), 1500)
	}

	return (
		<PaneAction
			aria-label={copied ? "Copied" : `Copy ${panelName} values for an agent`}
			title={copied ? "Copied" : "Copy values"}
			onClick={copy}
		>
			{copied ? <RiCheckLine /> : <RiFileCopyLine />}
		</PaneAction>
	)
}

function copyInstruction(panelName: string, values: Record<string, DialValue>): string {
	const json = JSON.stringify(
		Object.fromEntries(
			Object.entries(values).filter(([path]) => !path.endsWith(".__mode")),
		),
		null,
		2,
	)
	return `Update the useControls configuration for "${panelName}" with these values:

\`\`\`json
${json}
\`\`\`

Apply these values as the new defaults in the useControls call.`
}

// ── ControlsTransition ──

type TransitionMode = "easing" | "simple" | "advanced"

const DEFAULT_EASING: EasingConfig = {
	type: "easing",
	duration: 0.3,
	ease: [0.25, 0.1, 0.25, 1],
}

type ControlsTransitionProps = {
	panelId: string
	path: string
	label: string
	value: TransitionConfig
	onChange: (value: TransitionConfig) => void
}

// One control for easing curves and springs, as in DialKit: switching type
// swaps the value's shape and switching back restores the previous one
function ControlsTransition({
	panelId,
	path,
	label,
	value,
	onChange,
}: ControlsTransitionProps) {
	const mode: TransitionMode =
		value.type === "easing"
			? "easing"
			: springMode(value) === "physics"
				? "advanced"
				: "simple"

	const lastByMode = useRef<Record<TransitionMode, TransitionConfig>>({
		easing: DEFAULT_EASING,
		simple: DEFAULT_TIME_SPRING,
		advanced: DEFAULT_PHYSICS_SPRING,
	})
	const changeMode = (next: string) => {
		if (next !== "easing" && next !== "simple" && next !== "advanced") return
		lastByMode.current[mode] = value
		// Keep DialKit's own record of the mode in step for presets and persistence
		DialStore.updateTransitionMode(panelId, path, next)
		onChange(lastByMode.current[next])
	}

	return (
		<div data-slot="controls-transition" className="space-y-1 py-1">
			<ActionLabel className="w-auto">{label}</ActionLabel>
			{value.type === "easing" ? (
				<EasingCurveEditor
					value={{
						x1: value.ease[0],
						y1: value.ease[1],
						x2: value.ease[2],
						y2: value.ease[3],
					}}
					onChange={(bezier) =>
						onChange({
							...value,
							ease: [bezier.x1, bezier.y1, bezier.x2, bezier.y2],
						})
					}
				/>
			) : (
				<SpringCurve value={value} />
			)}
			<ControlsRow label="Type">
				<ToggleGroup
					type="single"
					value={mode}
					onValueChange={changeMode}
					className="w-full"
				>
					<ToggleGroupItem value="easing" className="flex-1">
						Easing
					</ToggleGroupItem>
					<ToggleGroupItem value="simple" className="flex-1">
						Time
					</ToggleGroupItem>
					<ToggleGroupItem value="advanced" className="flex-1">
						Physics
					</ToggleGroupItem>
				</ToggleGroup>
			</ControlsRow>
			{value.type === "easing" ? (
				<ControlsRow label="Duration">
					<NumberSlider
						value={value.duration}
						onChange={(duration) => onChange({ ...value, duration })}
						min={0.1}
						max={2}
						step={0.05}
						suffix="s"
					/>
				</ControlsRow>
			) : (
				<SpringFields value={value} onChange={onChange} />
			)}
		</div>
	)
}

function padAxis(axis: DialPadAxis | undefined): Required<XYPadAxis> {
	const [, min = -1, max = 1, step = 0.01] = axis ?? []
	return { min, max, step }
}

function isPadValue(value: DialValue | undefined): value is { x: number; y: number } {
	return (
		typeof value === "object" &&
		value !== null &&
		"x" in value &&
		"y" in value &&
		typeof value.x === "number" &&
		typeof value.y === "number"
	)
}

// Decimal places needed to display a step without rounding it away
function decimals(step: number): number {
	const fraction = String(step).split(".")[1]
	return fraction ? fraction.length : 0
}

export {
	Controls,
	ControlsCopy,
	ControlsField,
	ControlsPanel,
	ControlsVersions,
	type ControlsCopyProps,
	type ControlsFieldProps,
	type ControlsProps,
	type ControlsPanelProps,
	type ControlsVersionsProps,
}

"use client"

import { useEffect, useId, useMemo, useRef, useSyncExternalStore } from "react"
import {
	DialStore,
	flattenDialValueUpdates,
	resolveDialValues,
	type DialConfig,
	type DialKitPersistOptions,
	type DialKitValueUpdates,
	type ResolvedValues,
	type ShortcutConfig,
} from "dialkit/store"

// The config format and store come from DialKit (https://github.com/joshpuckett/dialkit,
// MIT, © Josh Puckett). This hook follows its useDialStorePanel lifecycle; the
// controls themselves are rendered by Substrate's <Controls />.

type UseControlsOptions = {
	/** Keep values across unmounts, and share them between mounts using the same id */
	id?: string
	/** Save values to browser storage; pass an object to choose the key or storage */
	persist?: DialKitPersistOptions
	/** Called with the path of a clicked action control, such as "replay" */
	onAction?: (path: string) => void
	/**
	 * Keyboard shortcuts by control path. Hold a slider's key and scroll, drag
	 * or move the pointer to adjust it; press a toggle's key to flip it.
	 */
	shortcuts?: Record<string, ShortcutConfig>
}

type ControlsController<T extends DialConfig> = {
	values: ResolvedValues<T>
	/** Update some values from code, using the same nesting as the config */
	setValues: (values: DialKitValueUpdates<T>) => void
	/** Restore the config defaults */
	reset: () => void
}

function useControls<T extends DialConfig>(
	name: string,
	config: T,
	options: UseControlsOptions = {},
): ResolvedValues<T> {
	return useControlsController(name, config, options).values
}

// The same panel as useControls, plus setters for driving it from code:
// loading a saved state, or applying a preset.
function useControlsController<T extends DialConfig>(
	name: string,
	config: T,
	options: UseControlsOptions = {},
): ControlsController<T> {
	const instanceId = useId()
	const hasStableId = options.id !== undefined
	const panelId = options.id ?? `${name}-${instanceId}`

	// Refs keep the effects below from re-running when the caller passes a
	// fresh object each render; the serialized config decides when to update.
	const configRef = useRef(config)
	configRef.current = config
	const persistRef = useRef(options.persist)
	persistRef.current = options.persist
	const onActionRef = useRef(options.onAction)
	onActionRef.current = options.onAction
	const shortcutsRef = useRef(options.shortcuts)
	shortcutsRef.current = options.shortcuts

	const serializedConfig = JSON.stringify(config)
	const serializedPersist = JSON.stringify(options.persist)
	const serializedShortcuts = JSON.stringify(options.shortcuts)

	useEffect(() => {
		DialStore.registerPanel(panelId, name, configRef.current, shortcutsRef.current, {
			retainOnUnmount: hasStableId,
			persist: persistRef.current,
		})
		return () => DialStore.unregisterPanel(panelId)
	}, [hasStableId, panelId, name])

	// Push config edits without re-registering, which would reset the values
	const mounted = useRef(false)
	useEffect(() => {
		if (!mounted.current) {
			mounted.current = true
			return
		}
		DialStore.updatePanel(panelId, name, configRef.current, shortcutsRef.current, {
			retainOnUnmount: hasStableId,
			persist: persistRef.current,
		})
	}, [hasStableId, panelId, name, serializedConfig, serializedPersist, serializedShortcuts])

	useEffect(
		() => DialStore.subscribeActions(panelId, (path) => onActionRef.current?.(path)),
		[panelId],
	)

	const flatValues = useSyncExternalStore(
		(listener) => DialStore.subscribe(panelId, listener),
		() => DialStore.getValues(panelId),
		() => DialStore.getValues(panelId),
	)

	const values = useMemo(
		() => resolveDialValues(configRef.current, flatValues),
		// eslint-disable-next-line react-hooks/exhaustive-deps
		[flatValues, serializedConfig],
	)

	return useMemo(
		() => ({
			values,
			setValues: (next: DialKitValueUpdates<T>) =>
				DialStore.updateValues(
					panelId,
					flattenDialValueUpdates(configRef.current, next),
				),
			reset: () => DialStore.resetValues(panelId),
		}),
		[values, panelId],
	)
}

export {
	useControls,
	useControlsController,
	type UseControlsOptions,
	type ControlsController,
}
export type {
	DialConfig as ControlsConfig,
	ResolvedValues as ControlsValues,
	ShortcutConfig as ControlsShortcut,
} from "dialkit/store"

import {
	DialStore,
	type ControlMeta,
	type ShortcutConfig,
} from "dialkit/store"

// Keyboard shortcuts for useControls panels, following DialKit's behaviour
// (MIT, © Josh Puckett): hold a slider's key and scroll, drag or move the
// pointer to adjust it, or use the arrow keys; press a toggle's key to flip it.
// One window listener serves every mounted <Controls />.

type Modifier = NonNullable<ShortcutConfig["modifier"]>
type Interaction = NonNullable<ShortcutConfig["interaction"]>

type Target = {
	panelId: string
	path: string
	control: ControlMeta
	shortcut: ShortcutConfig
}

type ActiveShortcut = { panelId: string; path: string } | null

/** Pixels of pointer travel per slider step when dragging or moving */
const DRAG_SENSITIVITY = 4

// ── Active shortcut, for highlighting the row being adjusted ──

let active: ActiveShortcut = null
const activeListeners = new Set<() => void>()

function setActive(next: ActiveShortcut) {
	if (active?.panelId === next?.panelId && active?.path === next?.path) return
	active = next
	activeListeners.forEach((listener) => listener())
}

function subscribeActiveShortcut(listener: () => void) {
	activeListeners.add(listener)
	return () => {
		activeListeners.delete(listener)
	}
}

function getActiveShortcut(): ActiveShortcut {
	return active
}

// ── Labels ──

function formatModifier(modifier: ShortcutConfig["modifier"]): string {
	return modifier === "alt" ? "⌥" : modifier === "shift" ? "⇧" : modifier === "meta" ? "⌘" : ""
}

/** "R+Scroll" for a slider, "V" for a toggle */
function formatShortcut(control: ControlMeta, shortcut: ShortcutConfig): string {
	const key = shortcut.key ? `${formatModifier(shortcut.modifier)}${shortcut.key.toUpperCase()}` : ""
	if (control.type === "toggle") return key || "Press"
	const interaction = shortcut.interaction ?? "scroll"
	const verb = interaction === "drag" ? "Drag" : interaction === "move" ? "Move" : "Scroll"
	return key ? `${key}+${verb}` : verb
}

// ── Slider maths ──

function effectiveStep(control: ControlMeta, shortcut: ShortcutConfig): number {
	const range = (control.max ?? 1) - (control.min ?? 0)
	const mode = shortcut.mode ?? "normal"
	if (mode === "fine") return range * 0.01
	if (mode === "coarse") return range * 0.1
	return control.step ?? 1
}

function roundToStep(value: number, step: number, min: number, max: number): number {
	const clamped = Math.max(min, Math.min(max, value))
	if (clamped === min || clamped === max || !(step > 0)) return clamped
	const snapped = min + Math.round((clamped - min) / step) * step
	return Math.max(min, Math.min(max, Number(snapped.toPrecision(14))))
}

function nudge(target: Target, steps: number) {
	const current = DialStore.getValue(target.panelId, target.path)
	if (typeof current !== "number") return
	const step = effectiveStep(target.control, target.shortcut)
	const min = target.control.min ?? 0
	const max = target.control.max ?? 1
	DialStore.updateValue(
		target.panelId,
		target.path,
		roundToStep(current + steps * step, step, min, max),
	)
}

// ── Resolution ──

function findControl(controls: ControlMeta[], path: string): ControlMeta | null {
	for (const control of controls) {
		if (control.path === path) return control
		if (control.children) {
			const found = findControl(control.children, path)
			if (found) return found
		}
	}
	return null
}

function modifierOf(event: KeyboardEvent | MouseEvent | WheelEvent): Modifier | undefined {
	if (event.altKey) return "alt"
	if (event.shiftKey) return "shift"
	if (event.metaKey) return "meta"
	return undefined
}

function resolveKey(key: string, modifier: Modifier | undefined): Target | null {
	for (const panel of DialStore.getPanels("panel")) {
		for (const [path, shortcut] of Object.entries(panel.shortcuts)) {
			if (shortcut.key?.toLowerCase() !== key) continue
			if (shortcut.modifier !== modifier) continue
			const control = findControl(panel.controls, path)
			if (control) return { panelId: panel.id, path, control, shortcut }
		}
	}
	return null
}

/** A held key's slider that uses the given interaction */
function resolveHeldSlider(held: Set<string>, interaction: Interaction): Target | null {
	for (const key of held) {
		for (const panel of DialStore.getPanels("panel")) {
			for (const [path, shortcut] of Object.entries(panel.shortcuts)) {
				if (shortcut.key?.toLowerCase() !== key) continue
				if ((shortcut.interaction ?? "scroll") !== interaction) continue
				const control = findControl(panel.controls, path)
				if (control?.type === "slider") {
					return { panelId: panel.id, path, control, shortcut }
				}
			}
		}
	}
	return null
}

function resolveScrollOnly(): Target | null {
	for (const panel of DialStore.getPanels("panel")) {
		for (const [path, shortcut] of Object.entries(panel.shortcuts)) {
			if (shortcut.interaction !== "scroll-only") continue
			const control = findControl(panel.controls, path)
			if (control?.type === "slider") {
				return { panelId: panel.id, path, control, shortcut }
			}
		}
	}
	return null
}

/**
 * Shortcuts pause while letter keys mean something else: typing in a field, or
 * type-ahead in a list or menu. Unlike DialKit, a focused button doesn't pause
 * them, since clicking any control would otherwise switch shortcuts off.
 */
function isEditing(): boolean {
	const element = document.activeElement
	if (!(element instanceof HTMLElement)) return false
	if (element.isContentEditable) return true
	if (element instanceof HTMLInputElement) {
		return !["button", "checkbox", "radio", "range", "reset", "submit", "color", "file"].includes(element.type)
	}
	return Boolean(
		element.closest(
			'textarea, select, [role="listbox"], [role="menu"], [role="combobox"], [role="textbox"]',
		),
	)
}

// ── Listener ──

function createListener() {
	const held = new Set<string>()
	let dragging = false
	let lastX: number | null = null
	let accumulated = 0

	const resetPointer = () => {
		dragging = false
		lastX = null
		accumulated = 0
	}

	const applyTravel = (target: Target, clientX: number) => {
		if (lastX === null) {
			lastX = clientX
			return
		}
		accumulated += clientX - lastX
		lastX = clientX
		const steps = Math.trunc(accumulated / DRAG_SENSITIVITY)
		if (steps === 0) return
		accumulated -= steps * DRAG_SENSITIVITY
		nudge(target, steps)
	}

	const handleKeyDown = (event: KeyboardEvent) => {
		if (isEditing()) return
		const key = event.key.toLowerCase()

		if (key.startsWith("arrow") && held.size > 0) {
			const target =
				resolveHeldSlider(held, "scroll") ??
				resolveHeldSlider(held, "drag") ??
				resolveHeldSlider(held, "move")
			if (target) {
				event.preventDefault()
				nudge(target, key === "arrowright" || key === "arrowup" ? 1 : -1)
				return
			}
		}

		const repeated = held.has(key)
		held.add(key)
		const target = resolveKey(key, modifierOf(event))
		if (!target) return
		setActive({ panelId: target.panelId, path: target.path })
		if (!repeated) {
			resetPointer()
			if (target.control.type === "toggle") {
				const current = DialStore.getValue(target.panelId, target.path)
				DialStore.updateValue(target.panelId, target.path, current !== true)
			}
		}
	}

	const handleKeyUp = (event: KeyboardEvent) => {
		held.delete(event.key.toLowerCase())
		resetPointer()
		let next: ActiveShortcut = null
		for (const key of held) {
			const target = resolveKey(key, modifierOf(event))
			if (target) {
				next = { panelId: target.panelId, path: target.path }
				break
			}
		}
		setActive(next)
	}

	const handleWheel = (event: WheelEvent) => {
		if (isEditing()) return
		const modifier = modifierOf(event)
		let target: Target | null = null
		for (const key of held) {
			const candidate = resolveKey(key, modifier)
			if (
				candidate?.control.type === "slider" &&
				(candidate.shortcut.interaction ?? "scroll") === "scroll"
			) {
				target = candidate
				break
			}
		}
		target ??= resolveScrollOnly()
		if (!target) return
		event.preventDefault()
		nudge(target, event.deltaY > 0 ? -1 : 1)
	}

	const handleMouseDown = (event: MouseEvent) => {
		if (isEditing() || held.size === 0) return
		if (!resolveHeldSlider(held, "drag")) return
		event.preventDefault()
		dragging = true
		lastX = event.clientX
		accumulated = 0
	}

	const handleMouseMove = (event: MouseEvent) => {
		if (isEditing() || held.size === 0) return
		const target = dragging
			? resolveHeldSlider(held, "drag")
			: resolveHeldSlider(held, "move")
		if (target) applyTravel(target, event.clientX)
	}

	const handleBlur = () => {
		held.clear()
		resetPointer()
		setActive(null)
	}

	window.addEventListener("keydown", handleKeyDown)
	window.addEventListener("keyup", handleKeyUp)
	window.addEventListener("wheel", handleWheel, { passive: false })
	window.addEventListener("mousedown", handleMouseDown)
	window.addEventListener("mouseup", resetPointer)
	window.addEventListener("mousemove", handleMouseMove)
	window.addEventListener("blur", handleBlur)

	return () => {
		window.removeEventListener("keydown", handleKeyDown)
		window.removeEventListener("keyup", handleKeyUp)
		window.removeEventListener("wheel", handleWheel)
		window.removeEventListener("mousedown", handleMouseDown)
		window.removeEventListener("mouseup", resetPointer)
		window.removeEventListener("mousemove", handleMouseMove)
		window.removeEventListener("blur", handleBlur)
		setActive(null)
	}
}

let users = 0
let stop: (() => void) | null = null

/** Start listening while at least one caller holds the returned release */
function retainShortcutListener(): () => void {
	users += 1
	if (users === 1) stop = createListener()
	return () => {
		users -= 1
		if (users === 0) {
			stop?.()
			stop = null
		}
	}
}

export {
	formatShortcut,
	getActiveShortcut,
	retainShortcutListener,
	subscribeActiveShortcut,
	type ActiveShortcut,
}
